create function public.checkout_quote(p jsonb) returns jsonb language plpgsql security invoker set search_path=public as $$declare sub bigint:=0;ship bigint:=0;disc bigint:=0;item jsonb;v products;promo promotions;zone shipping_zones;qty integer;begin
 if jsonb_typeof(p->'items')<>'array' or jsonb_array_length(p->'items') not between 1 and 100 then raise exception 'Invalid basket';end if;
 for item in select value from jsonb_array_elements(p->'items') loop qty:=(item->>'qty')::integer;if qty not between 1 and 9999 then raise exception 'Invalid quantity';end if;select * into v from products where id=(item->>'id')::uuid and status='published';if not found or v.stock-v.reserved<qty then raise exception 'A product is unavailable or has insufficient stock';end if;sub:=sub+v.price*qty;end loop;
 if p->>'method'='delivery' then select * into zone from shipping_zones where id=nullif(p->>'zone','')::uuid and active;if not found or not(zone.parishes ? (p->>'parish')) then raise exception 'Choose an approved delivery zone';end if;ship:=zone.rate;end if;
 if coalesce(p->>'promo','')<>'' then select * into promo from promotions where upper(code)=upper(p->>'promo') and active;if not found or (promo.starts_at is not null and promo.starts_at>now()) or (promo.ends_at is not null and promo.ends_at<now()) or (promo.max_uses is not null and promo.uses>=promo.max_uses) or sub<promo.minimum then raise exception 'Promotion is invalid, expired or ineligible';end if;disc:=case when promo.kind='percent' then floor(sub*promo.value/100.0) else least(sub,promo.value) end;end if;
 return jsonb_build_object('subtotal',sub,'shipping',ship,'discount',disc,'total',sub+ship-disc);end$$;
revoke all on function public.checkout_quote(jsonb) from public,anon,authenticated;grant execute on function public.checkout_quote(jsonb) to service_role;
